CREATE TABLE IF NOT EXISTS users(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, username VARCHAR(80) UNIQUE NOT NULL, password_hash VARCHAR(100) NOT NULL, role VARCHAR(30) NOT NULL, ref_id VARCHAR(30), failed_attempts INT NOT NULL DEFAULT 0, locked_until TIMESTAMP, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL);
CREATE TABLE IF NOT EXISTS customers(customer_id VARCHAR(30) PRIMARY KEY, customer_number VARCHAR(30) UNIQUE NOT NULL, customer_name VARCHAR(120) NOT NULL, email VARCHAR(150) UNIQUE NOT NULL, mobile_number VARCHAR(20) NOT NULL, customer_type VARCHAR(20) NOT NULL, city VARCHAR(80) NOT NULL, status VARCHAR(20) NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS telecom_services(service_id VARCHAR(30) PRIMARY KEY, service_code VARCHAR(30) UNIQUE NOT NULL, service_name VARCHAR(120) NOT NULL, service_type VARCHAR(40) NOT NULL, customer_id VARCHAR(30) NOT NULL REFERENCES customers(customer_id), activation_date DATE NOT NULL, service_status VARCHAR(20) NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS network_engineers(engineer_id VARCHAR(30) PRIMARY KEY, employee_code VARCHAR(30) UNIQUE NOT NULL, engineer_name VARCHAR(120) NOT NULL, specialization VARCHAR(80) NOT NULL, region VARCHAR(40) NOT NULL, experience_years INT NOT NULL, availability BOOLEAN NOT NULL, active_ticket_count INT NOT NULL DEFAULT 0, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS sla_configuration(priority VARCHAR(20) PRIMARY KEY, response_minutes INT NOT NULL, resolution_minutes INT NOT NULL);
CREATE TABLE IF NOT EXISTS trouble_tickets(ticket_id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, ticket_number VARCHAR(40) UNIQUE NOT NULL, customer_id VARCHAR(30) NOT NULL REFERENCES customers(customer_id), service_id VARCHAR(30) NOT NULL REFERENCES telecom_services(service_id), category VARCHAR(40) NOT NULL, description VARCHAR(2000) NOT NULL, priority VARCHAR(20) NOT NULL, severity VARCHAR(20) NOT NULL, created_date TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL, assigned_engineer_id VARCHAR(30) REFERENCES network_engineers(engineer_id), status VARCHAR(30) NOT NULL, sla_deadline TIMESTAMP NOT NULL, root_cause VARCHAR(1000), resolution VARCHAR(2000), resolution_code VARCHAR(40), resolution_date TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS idx_ticket_status_priority ON trouble_tickets(status,priority); CREATE INDEX IF NOT EXISTS idx_ticket_customer ON trouble_tickets(customer_id); CREATE INDEX IF NOT EXISTS idx_ticket_sla ON trouble_tickets(sla_deadline);
CREATE TABLE IF NOT EXISTS ticket_status_history(history_id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,ticket_id BIGINT NOT NULL REFERENCES trouble_tickets(ticket_id),old_status VARCHAR(30),new_status VARCHAR(30) NOT NULL,changed_by VARCHAR(80) NOT NULL,changed_date TIMESTAMP DEFAULT CURRENT_TIMESTAMP,remarks VARCHAR(1000));
CREATE TABLE IF NOT EXISTS escalation_history(escalation_id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,ticket_id BIGINT NOT NULL REFERENCES trouble_tickets(ticket_id),from_level VARCHAR(40),to_level VARCHAR(40) NOT NULL,reason VARCHAR(1000) NOT NULL,escalation_date TIMESTAMP DEFAULT CURRENT_TIMESTAMP,escalated_by VARCHAR(80) NOT NULL);
CREATE TABLE IF NOT EXISTS network_events(event_id VARCHAR(40) PRIMARY KEY,network_node VARCHAR(80) NOT NULL,event_type VARCHAR(40) NOT NULL,severity VARCHAR(20) NOT NULL,event_time TIMESTAMP NOT NULL,processed BOOLEAN DEFAULT FALSE,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS notifications(notification_id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,recipient_id VARCHAR(80) NOT NULL,message VARCHAR(1000) NOT NULL,notification_type VARCHAR(40) NOT NULL,created_date TIMESTAMP DEFAULT CURRENT_TIMESTAMP,read_status BOOLEAN DEFAULT FALSE,processed BOOLEAN DEFAULT FALSE);
CREATE TABLE IF NOT EXISTS feedback(feedback_id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,ticket_id BIGINT NOT NULL REFERENCES trouble_tickets(ticket_id),customer_id VARCHAR(30) NOT NULL REFERENCES customers(customer_id),rating INT NOT NULL CHECK(rating BETWEEN 1 AND 5),comments VARCHAR(1000),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS audit_log(audit_id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,actor VARCHAR(80) NOT NULL,action VARCHAR(80) NOT NULL,entity_type VARCHAR(50) NOT NULL,entity_id VARCHAR(50),details VARCHAR(2000),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS login_history(login_id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,username VARCHAR(80) NOT NULL,login_time TIMESTAMP DEFAULT CURRENT_TIMESTAMP,success BOOLEAN NOT NULL,ip_address VARCHAR(80),remarks VARCHAR(500));
CREATE VIEW IF NOT EXISTS v_ticket_sla AS SELECT t.ticket_number,t.priority,t.status,t.sla_deadline,CASE WHEN CURRENT_TIMESTAMP>t.sla_deadline THEN 'BREACHED' WHEN DATEDIFF('MINUTE',CURRENT_TIMESTAMP,t.sla_deadline)<=60 THEN 'AT_RISK' ELSE 'WITHIN_SLA' END sla_status FROM trouble_tickets t;
